    s = s.strip().lower()
    today = datetime.today()
    if s in ("today", "now"):
        return today.strftime("%Y-%m-%d")
    if s == "tomorrow":
        return (today + timedelta(days=1)).strftime("%Y-%m-%d")
    # common formats: YYYY-MM-DD, DD.MM.YYYY, DD/MM/YYYY, MM/DD/YYYY
    m = re.match(r"(\d{4})[-/](\d{1,2})[-/](\d{1,2})$", s)
