    m = re.match(r"(\d{1,2})[./](\d{1,2})[./](\d{4})$", s)
    if m:
        d, mo, y = m.groups()
        return f"{int(y):04d}-{int(mo):02d}-{int(d):02d}"
    # try parsing "next month" or "monthly" -> leave as keyword 'monthly' to schedule
    if "monthly" in s or "every month" in s or "each month" in s:
        return "monthly"
    # fallback: return original trimmed string
    return s

def find_amount(text: str):
    # find first number that plausibly represents amount, allow comma as decimal separator
    # Also allow formats like "1,200.50" or "1.200,50" or "1200"
    # Strategy: find tokens with digits and '.' or ',' then normalize
    tokens = re.findall(r'(?<!\w)(?:\d{1,3}(?:[.,]\d{3})*(?:[.,]\d+)?|\d+(?:[.,]\d+)?)(?!\w)', text)
    if not tokens:
        return None
    # Heuristic: choose the token closest to words '€' or 'eur' or 'amount' or 'rent'
    candidates = tokens
    def normalize_amount(tok):
        # choose interpretation: if both '.' and ',' present, assume '.' thousand and ',' decimal if ',' after last three digits else swap
        t = tok.replace(" ", "")
        if t.count(",") and t.count("."):
            # decide which is decimal: last separator probably decimal
            if t.rfind(",") > t.rfind("."):
                # comma decimal
                t = t.replace(".", "")
                t = t.replace(",", ".")
            else:
                t = t.replace(",", "")
        else:
            # if only comma, treat comma as decimal if digits after comma <=2
            if t.count(","):
                parts = t.split(",")
                if len(parts[-1]) <= 2:
                    t = t.replace(",", ".")
                else:
                    t = t.replace(",", "")
        try:
