    # keywords
    if re.search(r'\btoday\b', text, flags=re.IGNORECASE):
        return iso_date_from_match("today")
    if re.search(r'\btomorrow\b', text, flags=re.IGNORECASE):
        return iso_date_from_match("tomorrow")
    if re.search(r'\bmonthly\b|\bevery month\b|\beach month\b', text, flags=re.IGNORECASE):
        return "monthly"
    return None

